"Anyone remember why the sky is a portal?":"Se kdo spomni, zakaj je nebo portal?",
"They say if you jump in the shaft you pop out at the enemy's. Not testing it.":"Pravijo, da če skočiš v jašek, prideš ven pri sovražniku. Ne bom preizkušal.",
"The Swarm painted their visors red again. Show-offs.":"Roj je spet pobarval vizirje rdeče. Napihnjenci.",
"Ore, ore… when do we get some oil?":"Ruda, ruda… kdaj bomo dobili olje?",
"I dreamt I was a toaster. It was peaceful.":"Sanjal sem, da sem opekač. Bilo je mirno.",
"Quiet. Too quiet.":"Tiho. Preveč tiho.",
"See that? Our base is above the Swarm base again. Portals, man.":"Vidite? Nad bazo Roja je spet naša baza. Portali, no.",
"Diman, if you're reading this — we need a vacation.":"Diman, če to bereš — potrebujemo dopust.",
