"Autosaved":"Samodejno shranjeno",
"robot war · the sky is a portal":"vojna robotov · nebo je portal",
"Welcome to the meteor! You are a Consortium combat robot. Look around with the mouse and walk with WASD.":"Dobrodošel na meteorju! Si bojni robot Konsorcija. Poglej okoli z miško in hodi z WASD.",
"Jetpack: tap Shift to hop, hold Shift to fly. Energy recharges on the ground.":"Jetpack: tapni Shift za skok, drži Shift za let. Energija se polni na tleh.",
"Fire — LMB. Aim — RMB: more accurate, with zoom. Fire a few shots.":"Streljaj — LMB. Ciljanje — RMB: natančneje, s povečavo. Izstreli nekaj strelov.",
"Reload — R. Bullets hit hardest at medium range, 20–50 meters.":"Polnjenje — R. Naboji najmočneje zadenejo na srednji razdalji, 20–50 metrov.",
"Rocket — Q. For tanks and buildings. Fire a rocket.":"Raketa — Q. Za tanke in zgradbe. Izstreli raketo.",
"At the top is the strategist's order. Run along the green arrows: you sprint on the route. Capture the point — stay near the beacon.":"Na vrhu je naloga stratega. Teci po zelenih puščicah: na poti imaš šprint. Zavzemi točko — stoj blizu svetilnika.",
"Your squad has your back: their portraits and health are on the left. If they fall behind, they will ask you to wait.":"Tvoj oddelek te krije: njihovi portreti in zdravje so levo. Če zaostajajo, te bodo prosili, naj počakaš.",
"{0} — quick unit switch without leaving the battle: jump into the squad or tank closest to the fight. Try it.":"{0} — hitra menjava enote brez izhoda iz boja: skoči v oddelek ali tank, ki je najbližje spopadu. Poskusi.",
"Next to a tank or turret press E to take control. Or just carry on.":"Ob tanku ali kupoli pritisni E in prevzemi nadzor. Ali pa kar pojdi naprej.",
"Now strategy. Tap \"◩ Strategy\" at the top right — a top view of the battlefield.":"Zdaj strategija. Tapni »◩ Strategija« zgoraj desno — pogled na bojišče od zgoraj.",
"Now strategy. Press {0} (or \"◩ Strategy\" at the top left) — a top view of the battlefield.":"Zdaj strategija. Pritisni {0} (ali »◩ Strategija« zgoraj levo) — pogled na bojišče od zgoraj.",
"In strategy the Curator helps you: the box at the top says what to do, a frame shows the button, a ring marks the spot on the map. Complete three of its tips.":"V strategiji ti pomaga Vodnik: okno zgoraj pove, kaj storiti, okvir kaže gumb, obroč pa mesto na zemljevidu. Opravi tri njegove nasvete.",
"Select a squad and tap the green \"▶ Possess\" button — back into battle as that trooper. While you shoot, the AI strategist runs the army.":"Izberi oddelek in tapni zeleni gumb »▶ Prevzemi nadzor« — spet v boj kot ta vojak. Medtem ko streljaš, AI-strateg sam vodi vojsko.",
"Select a squad and press {0} or the green \"▶ Possess\" — back into battle as that trooper (nothing selected — your own). While you shoot, the AI strategist runs the army.":"Izberi oddelek in pritisni {0} ali zeleni »▶ Prevzemi nadzor« — spet v boj kot ta vojak (brez izbire — za svojega). Medtem ko streljaš, AI-strateg sam vodi vojsko.",
"Training complete! The Swarm is launching its offensive. Good luck, trooper!":"Urjenje opravljeno! Roj začenja ofenzivo. Srečno, vojak!",
