"{0} unlocks at rank \"{1}\". XP comes from kills, captures and strategist orders (×2–×3).":"{0} se odklene pri činu »{1}«. Izkušnje dobiš z ubijanjem, zavzemanjem točk in ukazi stratega (×2–×3).",
