"At the top is the AI strategist's order. Follow it: ×2 and ×3 XP, and completed orders can earn rewards. The green marker and chevrons lead the way.":"Zgoraj je ukaz AI-stratega. Izpolni ga: izkušnje ×2 in ×3, za izpolnitev pa so tudi nagrade. Zeleni označevalnik in puščice vodijo do cilja.",
"Shift — jump pack: tap to hop, hold to fly. RMB — aim.":"Shift — jetpack: dotik za skok, drži za let. Desni klik — ciljanje.",
