"Aim at the enemy cluster and call in a strike.":"Naceli skupino sovražnikov in pokliči udar.",
"Targets are far — the railgun is stronger at long range.":"Cilji so daleč — tirnični top je močnejši na veliki razdalji.",
"You have a temporary heavy MG — use it before it is recalled.":"Imaš začasni težki mitraljez — uporabi ga, preden ga prikličejo nazaj.",
"Parkour: C while running — slide, jump at a ledge — climb it, jump next to a wall in the air — wall-jump.":"Parkur: C med tekom — drsenje, skok ob polici — vzpon, skok ob steni v zraku — odbitek.",
"Bullets hit hardest at 20–50 m. Point-blank and long range are much weaker — for enemies too.":"Krogle najmočneje zadenejo na 20–50 m. Na blizu in na daleč so precej šibkejše — tudi za sovražnike.",
"Your robot is badly damaged. Get out of the fire — armor self-repairs out of combat.":"Tvoj robot je hudo poškodovan. Umakni se iz ognja — zunaj boja se oklep sam popravlja.",
"One of our tanks is close. Walk up and press E to take control.":"Blizu je naš tank. Pojdi do njega in pritisni E, da prevzameš nadzor.",
"Man the turret — press E next to it.":"Zasedi kupolo — E ob njej.",
"It is quiet here. Switch to a squad or vehicle closer to the fight.":"Tukaj je mirno. Preklopi na oddelek ali tehniko bliže boju.",
"Reload early while no enemies are around.":"Napolni vnaprej, dokler ni sovražnikov.",
"Sprint right along the strategist's green chevrons — you run faster on his route.":"Teci točno po zelenih puščicah stratega — na njegovi poti tečeš hitreje.",
"\"◩ Strategy\" button — top view: build the base, order troops, command squads.":"Gumb »◩ Strategija« — pogled od zgoraj: gradi bazo, naroči vojake, poveljuj oddelkom.",
"Strategy mode: build the base, order troops, call strikes and command squads. The same key there possesses the selected unit.":"Način strategije: gradi bazo, naroči vojake, kliči udare in poveljuj oddelkom. Ista tipka tam prevzame izbrano enoto.",
"Want full command? Turn off the AI strategist — then you give the orders.":"Hočeš poveljevati sam? Izklopi AI-stratega — potem ukaze daješ ti.",
"Third-person view — to see your robot.":"Pogled iz tretje osebe — da vidiš svojega robota.",
"Tank: {0} — barrage at your aim point, {1} — smoke screen, {2} — overdrive. {3} — back to infantry.":"Tank: {0} — plaz v točko ciljanja, {1} — dimna zavesa, {2} — forsaž. {3} — nazaj v pehoto.",
"Plenty of targets — fire a barrage.":"Ciljev je veliko — sproži plaz.",
"Drone: {0}/{1} — up/down, LMB — fire, {2} — ram your aim point.":"Dron: {0}/{1} — više/niže, levi klik — ogenj, {2} — ovn v točko ciljanja.",
"Select a squad — LMB, drag a box or a card on the left. RMB on the ground — attack-move ⚔, on an enemy — attack, on a point — capture.":"Izberi oddelek — levi klik, okvir ali kartica levo. Desni klik na tla — napadalno premikanje ⚔, na sovražnika — napad, na točko — zavzetje.",
"Squads have abilities: grenades, jet leap, suppression, repair. Tanks: barrage, smoke, overdrive.":"Oddelki imajo sposobnosti: granate, skok z jetpackom, zatiranje, popravilo. Tanki: plaz, dim, forsaž.",
"Plenty of ore — select the HQ or a factory and order troops in its panel on the right.":"Rude je veliko — izberi štab ali tovarno in naroči vojake v njeni plošči desno.",
"Command points are piling up — \"Powers\" tab: recon, artillery, squad drop pod, orbital strike.":"Točke poveljevanja se kopičijo — zavihek »Udari«: izvidovanje, topniški udar, pristajalna kapsula z oddelkom, orbitalni udar.",
"Only builders construct buildings: select a builder (button in the Build tab or a building key), then click the spot. An extractor (C) on a glowing vein — more ore.":"Zgradbe gradijo samo inženirji: izberi inženirja (gumb v zavihku »Gradnja« ali tipka zgradbe), nato klikni na mesto. Ekstraktor (C) na svetleči žili — več rude.",
"Click \"ORE\" at the top left — where ore comes from and how to boost income.":"Klikni »RUDA« zgoraj levo — od kod prihaja ruda in kako pospešiti dohodek.",
"Ctrl+1…9 — save a group, 1…9 — select it, double-tap — jump the camera.":"Ctrl+1…9 — shrani skupino, 1…9 — izberi jo, dvojni dotik — kamera k njej.",
"Select a unit and tap the green \"▶ Possess\" below (or double tap) to fight yourself. \"◩ Strategy\" brings you back.":"Izberi enoto in tapni zeleni »▶ Prevzemi nadzor« spodaj (ali dvojni dotik) — boriš se sam. »◩ Strategija« te vrne sem.",
"Select a unit and press the green \"▶ Possess\" below or {0} (or double-click) to fight yourself. In battle {1} brings you back.":"Izberi enoto in pritisni zeleni »▶ Prevzemi nadzor« spodaj ali {0} (ali dvojni klik) — boriš se sam. V boju te {1} vrne nazaj.",
"Grey buttons can be pressed too: you will see what is missing, how long to wait and how to fix it.":"Sive gumbe lahko tudi pritisneš: pokazali bomo, kaj manjka, koliko čakati in kako popraviti.",
"RMB on the ground — rally point for this building's new troops.":"Desni klik na tla — zbirna točka za nove vojake te zgradbe.",
"RMB — attack-move ⚔: they stop to fight enemies they meet, then continue. Double RMB — march »: run without stopping, firing on the move. Hold/Retreat — \"More orders ▾\".":"Desni klik — napadalno premikanje ⚔: ob srečanju s sovražnikom se ustavijo in se borijo, nato gredo naprej. Dvojni desni klik — pohod »: tečejo brez ustavljanja in streljajo med tekom. Drži/Umik — »Več ukazov ▾«.",
"Camera: drag with a finger, two fingers — zoom and rotate, drag on the minimap too.":"Kamera: vleci s prstom, z dvema — povečava in vrtenje, vleči je mogoče tudi minimapo.",
"Camera: WASD and screen edges, Q/E rotate, wheel zoom (to cursor), MMB orbit, minimap — click or drag, Space — to the latest alert.":"Kamera: WASD in robovi zaslona, Q/E vrtenje, kolesce povečava (proti kazalcu), srednji klik vrtenje, minimapa — klik ali vleči, preslednica — k zadnjemu alarmu.",
