"New in v6.3":"Novo v v6.3",
"New in v6.2":"Novo v v6.2",
"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"Nov videz rude: žile so svetleči smaragdni brušeni kristali na črnem bazaltu z iskrami in zeleno meglico; ekstraktor je šestkotno podnožje s satasto kupolo in rešetkastim stolpom z zeleno svetilko (proga in zastavica v barvi ekipe)",
"New in v6.1":"Novo v v6.1",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Prednostni razred za prevzem nadzora kot v Battlefieldu (U, številke po smrti): ponovno se pojaviš kot tak vojak, če je na voljo",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"Tehnika iz prve osebe (V — od zunaj/iz kabine); rahla pomoč pri ciljanju — v Nastavitvah",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"Iz jedra se zdaj zlahka rešiš: preslednica — k jašku, B — kapsula na površje; učinki sposobnosti se ob smrti ponastavijo",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Neskončno napredovanje: generali in maršal ★, stopnje kariere, mojstrstvo orožja in dodatki, medalje, dnevne pogodbe — zaslon »Kariera«",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Strategija: gladek zoom s kolescem, ikone in oznake nad enotami (Alt — vse), plošča »Čete / Zgradbe« na levi",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"Desni klik — napad med premikom, dvojni desni klik — pohod s streljanjem med hojo; redki ukazi — v »Več ukazov ▾«; brez podvojenih gumbov",
"New in v6":"Novo v v6",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Orožje kot v strelcih: takojšnji streli, puška 720 strelov/min, mitraljez, odsun, ciljanje z desnim klikom, nabojniki in ponovno polnjenje R, oznake zadetkov",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Močnejša gravitacija, odzivnejši jetpack, sunek na Z ali dvojni jetpack v zraku; pri menjavi enote orožje ne leti več zraven",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Inženirji: izberi inženirja, izberi zgradbo, postavi načrt; ekstraktorji na rudnih žilah; klik na »RUDA« pokaže dohodek in kako ga povečati",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Sivi gumbi razložijo razlog in ponudijo rešitev; večji gumbi, trak »V teku«, »▶ Prevzemi nadzor«, Tab je edina tipka za način",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Strateška kamera brez sunkov in obratov, zoom na kazalec, minimapo lahko vlečeš",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Nova vozila: raider »Jackal«, »Grad« (samonavodljive rakete), minomet »Hammer«; Roj dobi »Wasp«, »Hive«, »Trebuchet«",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"Strateg ohrani ukaze in preneha spamati z glasom; boji pridejo k tebi; B — prerazporeditev, Shift+B — v boj; kompas, H — katera tarča",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Svobodno igranje (K) in samostojno delovanje (J), F2 — prednastavitve; Esc ustavi in nadaljuje; shranjevanje: reže, izvoz in uvoz",
"New in v5.3":"Novo v v5.3",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"Let: močnejša težnost daleč od meteorja, C v zraku zavira, potisk zavija ostreje; ne obvisiš več v portalu",
