"Builders are trained at the HQ — its panel is open on the right":"Inženirje naročaš v štabu — njegova plošča je odprta na desni",
"pick a building → tap a spot → \"Build\"":"izberi stavbo → dotakni se mesta → »Gradi«",
"pick a building → LMB on a spot (Shift — several)":"izberi stavbo → levi klik na mesto (Shift — več)",
"The selected builders do the building. RMB on your building — repair.":"Gradijo izbrani inženirji. Desni klik na svojo stavbo — popravilo.",
"Select a builder to build":"Izberi inženirja za gradnjo",
"Only builders construct. Click a builder on the map or press the button.":"Stavbe gradijo samo inženirji. Klikni inženirja na zemljevidu ali pritisni gumb.",
