"The Consortium heavy gunner is now a real rigged 3D model: idles, walks, charges with his gun, fires on the move and falls when destroyed":"Težki strelec Konzorcija je zdaj pravi 3D-model s skeletom: miruje, hodi, teče z orožjem, strelja med hojo in pade, ko je uničen",
"The model follows the meteor surface normal, turns its torso to aim and holds the machine gun; far away the animation updates less often to keep FPS":"Model stoji po normali površine meteorja, trup obrača proti cilju in drži mitraljez v rokah; od daleč se animacija posodablja redkeje, da FPS ne pade",
