"Heavy bunker with AT gun":"Težki bunker s protitankovskim topom",
"A second bunker with an anti-tank gun (vehicles out to 110 m); the pillbox gets armour plates and the outpost +35% HP.":"Drugi bunker s protitankovskim topom (vozila do 110 m); bunker dobi oklepne plošče, predstraža pa +35 % trdnosti.",
"Support":"Podpora",
"Repair-drone bay":"Hangar popravljalnih dronov",
"Three repair drones fix friendly robots, vehicles and buildings within 28 m.":"Trije popravljalni droni popravljajo svoje robote, vozila in zgradbe v radiju 28 m.",
"Force-field dome":"Silovno kupolasto polje",
"A 24 m dome: friendlies inside take 38% less damage.":"Kupola z radijem 24 m: svoji znotraj prejmejo 38 % manj škode.",
"Recon":"Izvidništvo",
"Radio scanner":"Radijski skener",
"A scanner mast clears the fog of war within 150 m.":"Jambor s skenerjem odstrani meglo vojne v radiju 150 m.",
"Sniper & spotter tower":"Ostrostrelski opazovalni stolp",
"Vision 190 m, marks enemies for the whole army (160 m), artillery and MLRS are twice as accurate there, and a sniper on top shoots infantry.":"Pregled 190 m, označuje sovražnike za vso vojsko (160 m), topništvo in MLRS sta tam dvakrat natančnejša, ostrostrelec na stolpu pa strelja po pehoti.",
"Armour plating":"Oklepne plošče",
"HQ +50% HP and −25% damage taken.":"Štab +50 % trdnosti in −25 % škode.",
"Defence turrets":"Obrambne kupole",
"4 twin turrets on the HQ platform: infantry, drones and light vehicles within 95 m.":"4 dvojne kupole na ploščadi štaba: pehota, droni in lažja vozila do 95 m.",
"Faster orbital drop":"Hitrejši orbitalni spust",
"A homing beacon: squads and solos from the barracks, builders and the drop pod are 35% faster, the pod is 25% cheaper.":"Navigacijski svetilnik: oddelki in posamezniki iz vojašnice, inženirji in pristajalna kapsula so pripravljeni 35 % hitreje, kapsula je 25 % cenejša.",
"Ore refinery columns":"Rudarski rafinerijski stolpi",
"Income +25%.":"Dohodek +25 %.",
"Global radar":"Globalni radar",
"Every 40 s a pulse reveals every enemy on the meteor for 6 s.":"Vsakih 40 s impulz: vsi sovražniki na meteorju so vidni 6 s.",
"Comms array":"Komunikacijske antene",
"+2 command points now and +1 more every 40 s (strikes, strategist powers).":"+2 poveljniške točke takoj in še +1 vsakih 40 s (udari, sposobnosti stratega).",
