"Pod on point {0}: {1}{2}{3}. The builder can place an outpost (V) and pick an upgrade branch.":"Kapsula na točki {0}: {1}{2}{3}. Inženir lahko postavi predstražo (V) in izbere vejo nadgradenj.",
