"Builders nearby":"Inženirjev v bližini",
"{0} is heading to the outpost":"{0} gre k predstraži",
"From the very start your base has the whole army, one of each: sky troopers, lone heavy gunner, sniper, scout, drone, raider, MLRS, mortar (plus assault squads and a tank) — possess anyone right away":"Od samega začetka boja v štabu stoji vsa vojska po en kos: padalci, mitraljezec posameznik, ostrostrelec, izvidnik, dron, napadalec, MLRS, minomet (ter jurišni oddelki s tankom) — takoj prevzemi nadzor nad kom koli",
"\"Custom order\" for possession (pause menu, ☰ on the phone): each class has a number, 1 is the top; ▲▼ change it, ✕ means never. After death and on X you get the unit closest to the fight in that order":"»Lasten vrstni red« prevzema (pavza, na telefonu ☰): vsak razred ima številko, 1 je glavna; ▲▼ jo spremenita, ✕ pomeni nikoli. Po smrti in na X dobiš vojaka, ki je po tem vrstnem redu najbližje boju",
"Bots are no longer snipers: they miss at range, on the move, against runners and targets in cover; bullets whizz past you and kick up dirt and cover nearby. Explosions knock you down: flinch, to one knee, off your feet and back up":"Boti niso več ostrostrelci: zgrešijo od daleč, med tekom, tekače in tarče v kritju; mimo tebe žvižgajo krogle in zadevajo tla ter kritje ob tebi. Eksplozije te podrejo: trzaj, na koleno, z nog in vstajanje",
"Capture a point and a pod drops a squad and a builder. An outpost on the point upgrades along one branch: defence (MG bunker → heavy bunker with AT gun), support (repair drones → force-field dome), recon (radio scanner → sniper & spotter tower)":"Zavzemi točko in kapsula spusti oddelek in inženirja. Predstraža na točki se nadgrajuje po eni veji: obramba (bunker → težki bunker s protitankovskim topom), podpora (popravljalni droni → silovna kupola), izvidništvo (radijski skener → ostrostrelski stolp)",
"The HQ upgrades too: armour plating, defence turrets, faster orbital drop, +25% income, global radar, comms array (+command points). The AI does the same":"Tudi štab se nadgrajuje: oklepne plošče, kupole, hitrejši orbitalni spust, dohodek +25 %, globalni radar, komunikacijske antene (+poveljniške točke). UI počne enako",
"New in v7.0":"Novo v v7.0",
"Your base has one of every unit and vehicle: sky troopers, sniper, scout, drone, raider, MLRS, mortar. Select any and {0} — try them before you even build.":"V štabu je po en vojak in vozilo vsakega tipa: padalci, ostrostrelec, izvidnik, dron, napadalec, MLRS, minomet. Izberi kogar koli in {0} — preizkusi jih, preden se zgradiš.",
"POSSESS":"PREVZEMI",
"Point {0}: a builder landed with the pod. Select it and place an \"Outpost\"{1} by the point — then pick an upgrade branch.":"Točka {0}: s kapsule se je izkrcal inženir. Izberi ga in ob točki postavi »Predstražo«{1} — nato izberi vejo nadgradenj.",
"OUTPOST":"PREDSTRAŽA",
"The outpost is ready — select it and pick a branch: ⛨ Defence (MG bunker, AT bunker), ✚ Support (repair drones, force-field dome) or ◎ Recon (scanner, sniper tower). A builder nearby does the work.":"Predstraža je pripravljena — izberi jo in izberi vejo: ⛨ Obramba (bunker, bunker s protitankovskim topom), ✚ Podpora (popravljalni droni, silovna kupola) ali ◎ Izvidništvo (skener, ostrostrelski stolp). Gradi inženir v bližini.",
"UPGRADE":"NADGRADI",
"The HQ is a \"super point\": select it{0} — armour, turrets, faster drops, +25% income, radar, comms.":"Štab je »super točka«: izberi ga{0} — oklepne plošče, kupole, hitrejši spust, dohodek +25 %, radar, antene.",
"☰ → \"Possession\": turn on \"Custom order\" and choose who you take after death — #1, #2… ✕ means never.":"☰ → »Prevzem«: vklopi »Lasten vrstni red« in izberi, koga prevzameš po smrti — št.1, št.2… ✕ pomeni nikoli.",
"Esc → pause → \"Custom order\": choose who you take after death and on X — #1, #2… ✕ means never.":"Esc → pavza → »Lasten vrstni red«: izberi, koga prevzameš po smrti in na X — št.1, št.2… ✕ pomeni nikoli.",
