"Possess at the Polygon":"Prevzemi nadzor na poligonu",
"Camera to the Polygon":"Kamera na poligon",
"Phone: new shooter controls — stick, Fire and Jet on the left, look by swipe or a second stick on the right; AUTO locks on with a red frame like Syphon Filter: your trooper keeps the target and fires, the stick circles around it, a swipe flicks to the next target":"Telefon: novo upravljanje strelca — levo krmilka, »Ogenj« in »Jet«, desno pogled s potegom ali krmilko; »AVTO« zaklene cilj z rdečim okvirjem kot v Syphon Filter: tvoj vojak sam drži cilj in strelja, s krmilko krožiš okoli njega, s potegom preskočiš na naslednji cilj",
"Gestures: double tap on the right — reflex; tap the red frame — rocket, swipe \"Grenade\" up — a grenade right at the target (or variant B — pinch); first-run gesture hints, icons instead of words, skills and \"hide HUD\" at the top":"Kretnje: dvojni dotik desno — refleks; tapni rdeči okvir — raketa, poteg »Granate« navzgor — granata natančno v cilj (ali različica B — ščip); namigi za kretnje ob prvem zagonu, ikone namesto besed, zgoraj veščine in »skrij HUD«",
"Strategy on the phone: tap to select and order, hold for a radial menu (attack, hold, patrol, build, rally), hold and drag for a box, double tap for all of a type on screen; infantry / vehicles / drones / builders buttons, squad cards 1-2-3, follow camera, haptic ticks":"Strategija na telefonu: dotik — izberi in ukaži, drži — krožni meni (napad, drži položaj, patrulja, gradnja, zbor), drži in vleci — okvir, dvojni dotik — vsi taki na zaslonu; gumbi »pehota / vozila / droni / inženirji«, kartice oddelkov 1-2-3, sledenje s kamero, haptični odziv",
"Phone menus without sliders or scrolling: every section is its own screen with big buttons, languages as flags, \"− value +\", \"Back / ✕ / Apply\"":"Meniji na telefonu brez drsnikov in drsenja: vsak razdelek je svoj zaslon z velikimi gumbi, jeziki kot zastave, »− vrednost +«, »Nazaj / ✕ / Uporabi«",
"Developer mode: \"Polygon\" in the Arsenal — an endless battle of every squad type and vehicle at the map centre with reinforcements for both sides; X takes you straight into a soldier there (PC and phone)":"Razvijalski način: »Poligon« v Arzenalu — neskončen boj oddelkov vseh vrst in vsega orožja v središču karte z okrepitvami za obe strani; X te takoj prestavi v vojaka na poligonu (PC in telefon)",
"PC":"PC",
"Move the mouse to turn your view.":"Premikaj miško — pogled se obrača.",
"{0} {1} {2} {3} — walk. Reach the green marker.":"{0} {1} {2} {3} — hoja. Pridi do zelene oznake.",
"Hold {0} — the jetpack lifts you up.":"Drži {0} — jetpack te dvigne v zrak.",
"Take off ({0}) and press {1} in the air — brake.":"Vzleti ({0}) in v zraku pritisni {1} — zavora.",
"Aim at a dummy and press LMB.":"Pomeri na tarčo in pritisni levi klik.",
"Hold RMB — aim with zoom.":"Drži desni klik — merjenje s povečavo.",
"Press {0}.":"Pritisni {0}.",
"Aim at a dummy and press {0}.":"Pomeri na tarčo in pritisni {0}.",
"Press {0} to throw (hold longer — farther).":"Pritisni {0} za met (drži dlje — dlje leti).",
"Get behind the wall until the sniper marker turns grey.":"Pojdi za zid, dokler oznaka ostrostrelca ne postane siva.",
"Press {0} — \"squad with me ⇄ going solo\".":"Pritisni {0} — »oddelek z menoj ⇄ delujem sam«.",
"Press {0} or \"◩ Strategy\" at the top left.":"Pritisni {0} ali »◩ Strategija« zgoraj levo.",
"Press {0} or the green \"▶ Possess\" below.":"Pritisni {0} ali zeleni »▶ Prevzemi nadzor« spodaj.",
"W A S D or arrows move the camera (or push the mouse to the screen edge).":"W A S D ali puščice premikajo kamero (ali potisni miško k robu zaslona).",
"Scroll the mouse wheel.":"Vrti kolesce miške.",
"LMB on the squad with the green marker.":"Levi klik na oddelek z zeleno oznako.",
"RMB on the yellow marker on the ground (double RMB — run).":"Desni klik na rumeno oznako na tleh (dvojni desni klik — tek).",
"Ctrl + LMB on a squad — all of that type on screen get selected.":"Ctrl + levi klik na oddelek — izbrani bodo vsi taki na zaslonu.",
"Hold LMB on empty ground and drag a box over the squads.":"Drži levi klik na praznem mestu in povleci okvir čez oddelke.",
"LMB on the minimap at the bottom left — the camera jumps there.":"Levi klik na minikarto spodaj levo — kamera skoči tja.",
"LMB on the marked builder (or \".\" — nearest builder).":"Levi klik na označenega inženirja (ali ».« — najbližji inženir).",
"\"Barracks\" on the right ({0}), then LMB on the ground at the marker.":"Desno »Vojašnica« ({0}), nato levi klik na tla pri oznaki.",
"No input needed — watch the building rise.":"Nič ni treba pritiskati — glej, kako stavba raste.",
"LMB on the Barracks → \"Assault squad\" on the right.":"Levi klik na Vojašnico → desno »Jurišni oddelek«.",
"Select a builder and RMB on the green crystals.":"Izberi inženirja in desni klik na zelene kristale.",
"Drag a finger on the right half of the screen.":"Vleci s prstom po desni polovici zaslona.",
"Touch the left side and slide — that is the stick. Reach the green marker.":"Dotakni se leve strani in vleci — to je krmilka. Pridi do zelene oznake.",
"Hold the \"Jet\" button.":"Drži gumb »Jet«.",
"Aim at a dummy with your right finger and hold \"Fire\".":"Z desnim prstom pomeri na tarčo in drži »Ogenj«.",
"Tap \"Reload\".":"Tapni »Napolni«.",
"Tap \"AUTO\" — a red frame locks the dummy and your trooper fires.":"Tapni »AVTO« — rdeči okvir zaklene tarčo in vojak strelja sam.",
"Tap the red frame on the target — a rocket flies. (No frame? Turn on \"AUTO\".)":"Tapni rdeči okvir na cilju — raketa poleti. (Ni okvirja? Vklopi »AVTO«.)",
"Rocket fired from the skills row. Try tapping the red frame itself.":"Raketa je izstreljena prek veščin. Poskusi tapniti sam rdeči okvir.",
"Swipe up on \"Grenade\" — it flies right at the target.":"Povleci navzgor po »Granati« — poleti natančno v cilj.",
"That was a normal throw. Now swipe up on the button — at the target.":"To je bil navaden met. Zdaj povleci navzgor po gumbu — v cilj.",
"Double tap quickly on the right half of the screen.":"Hitro dvakrat tapni desno polovico zaslona.",
"Tap the lightning bolt at the top right — the skills row opens.":"Tapni strelo zgoraj desno — odpre se vrstica veščin.",
"Use the stick to get behind the wall until the sniper marker turns grey.":"S krmilko pojdi za zid, dokler oznaka ostrostrelca ne postane siva.",
"Tap \"⇆\" at the top right.":"Tapni »⇆« zgoraj desno.",
