"Tap \"◩ Strategy\" at the top right.":"Tapni »◩ Strategija« zgoraj desno.",
"Tap \"▶ To battle\" at the top right (or \"Possess\" on the card).":"Tapni »▶ V boj« zgoraj desno (ali »Prevzemi nadzor« na kartici).",
"Drag one finger across the map.":"Vleci z enim prstom po karti.",
"Pinch with two fingers — closer / farther.":"Ščip z dvema prstoma — bliže / dlje.",
"Tap the squad with the green marker.":"Tapni oddelek z zeleno oznako.",
"Tap the yellow marker on the ground (double tap — run).":"Tapni rumeno oznako na tleh (dvojni dotik — tek).",
"Double tap a squad — all of that type on screen get selected.":"Dvakrat tapni oddelek — izbrani bodo vsi taki na zaslonu.",
"Hold a finger on empty ground until the yellow ring, then drag — a box appears.":"Drži prst na praznem mestu do rumenega obroča, nato vleci — nastane okvir.",
"Hold a finger on the ground at the marker until the ring, then release — a radial menu opens.":"Drži prst na tleh pri oznaki do obroča, nato spusti — odpre se krožni meni.",
"Tap card \"2\" on the left (double tap — camera to the squad).":"Tapni kartico »2« levo (dvojni dotik — kamera na oddelek).",
