"training complete":"urjenje opravljeno",
"Tap \"Aim\" to zoom in. Tap again to zoom out.":"Tapni »Merjenje« za povečavo. Še en dotik — nazaj.",
"Your squad follows you. Open ☰ → \"Pause\" → the \"Squad with me\" tile — it becomes \"Going solo\".":"Tvoj oddelek te spremlja. Odpri ☰ → »Pavza« → ploščico »Oddelek z menoj« — postane »Delujem sam«.",
"The builder is selected — tap \"◆ Mine crystals\" on its card below (or tap the green crystals).":"Inženir je izbran — tapni »◆ Pridobivaj kristale« na njegovi kartici spodaj (ali tapni zelene kristale).",
"Training complete!":"Urjenje opravljeno!",
"steps":"korakov",
"You can build a base, order troops, command and jump into battle. Next — a real match: the Curator will help as you play.":"Znaš graditi bazo, naročati enote, poveljevati in skakati v boj. Naprej — prava tekma: Vodnik ti bo svetoval med igro.",
"You can move, fly, shoot, take cover and command your squad. Next — a real match.":"Znaš se premikati, leteti, streljati, se skrivati in poveljevati oddelku. Naprej — prava tekma.",
"Real battle":"Pravi boj",
"Again":"Še enkrat",
"done":"opravljeno",
"you are on PC: keyboard and mouse":"imaš PC: tipkovnica in miška",
"you are on a phone: touch screen":"imaš telefon: zaslon na dotik",
"A safe sandbox: enemies are still dummies, nobody shoots at you. A step counts only when you actually do the action.":"Varen peskovnik: sovražniki so še vedno tarče, nihče ne strelja nate. Korak se šteje samo, ko dejanje res narediš.",
"Show others (training for the other device)":"Pokaži druge (urjenja za drugo napravo)",
"Old training (v7.1)":"Staro urjenje (v7.1)",
"Back to the normal device mode":"Vrni običajni način naprave",
"Training for the other device reloads the page in its mode (PC — mouse and keyboard, phone — touch; on a PC you can test touch in Chrome: F12 → phone icon).":"Urjenje za drugo napravo znova naloži stran v njenem načinu (PC — miška in tipkovnica, telefon — dotik; na PC-ju lahko dotik preizkusiš v Chromu: F12 → ikona telefona).",
"Training ×4: separate step-by-step \"Strategy\" and \"Shooter\" lessons for PC and for phone. A safe sandbox with dummies, the right button highlighted, arrows, animated keys, mouse and gestures; a step counts only for the real action, \"repeat step\", progress at the top and a reward at the end":"Urjenje ×4: ločena korak-za-korakom lekcije »Strategija« in »Strelec« za PC in za telefon. Varen peskovnik z lutkami, osvetljen pravi gumb, puščice, animirane tipke, miška in kretnje; korak se šteje samo za pravo dejanje, »ponovi korak«, napredek na vrhu in nagrada na koncu",
"The Training menu shows the lessons for your device; \"Show others\" — all four on any device; the \"Old training (v7.1)\" is still there":"Meni Urjenje sam pokaže lekcije za tvojo napravo; »Pokaži druge« — vse štiri na kateri koli napravi; »Staro urjenje (v7.1)« je še vedno tam",
"New in v7.2":"Novo v v7.2",
"NEW IN v7.2":"NOVO V v7.2",
"No grenades left":"Granate so pošle",
"Rocket and grenade recharging · {0} s":"Raketa in granata se polnita · {0} s",
"Left — move, right — look · tap an enemy — rocket / grenade · 2 taps — reflex · 3 taps — artillery strike":"Levo — hoja, desno — pogled · dotik na sovražnika — raketa / granata · 2 dotika — refleks · 3 dotiki — topniški udar",
"Less":"Manj",
"More":"Več",
"Enemy vehicle or structure nearby — tap it: a rocket flies.":"Sovražnikovo vozilo ali zgradba je blizu — dotakni se je: izstreli se raketa.",
"Lots of hostiles — double tap an empty spot on the right: reflex slows time down.":"Veliko sovražnikov — dvakrat hitro se dotakni praznega mesta na desni: refleks upočasni čas.",
"Aim at the enemy cluster and tap 3 times — artillery strike.":"Namerite na skupino sovražnikov in se dotakni 3-krat — topniški udar.",
"Left thumb — move, right thumb — look. Fires by itself when aimed at an enemy.":"Levi palec — hoja, desni — pogled. Ko ciljaš na sovražnika, strelja sam.",
"⇑ at the left edge — jetpack: tap to hop, hold to fly.":"⇑ ob levem robu — jetpack: dotik za skok, drži za let.",
"Old v7.2 layout":"Stara postavitev v7.2",
"Drag a finger on the right half of the screen — a look stick appears under it.":"Povleci s prstom po desni polovici zaslona — pod prstom se pojavi palica za pogled.",
"Touch the left side and slide — a stick appears under your finger. Reach the green marker.":"Dotakni se leve strani in povleci — pod prstom se pojavi palica. Pridi do zelenega označevalca.",
"Hold the \"Jet\" button at the left edge.":"Drži gumb »Jet« ob levem robu.",
"Aim at a dummy with the right stick — your trooper fires by itself when the crosshair is on it.":"Z desno palico naciljaj na lutko — tvoj vojak strelja sam, ko je merek na njej.",
"Tap the dummy on the screen — a rocket flies.":"Dotakni se lutke na zaslonu — izstreli se raketa.",
"Tap the dummy — a grenade flies in an arc, right at it.":"Dotakni se lutke — granata leti v loku, naravnost vanjo.",
"Double tap an empty spot on the right quickly.":"Hitro se dvakrat dotakni praznega mesta na desni.",
"Lite mode for weak phones: lower resolution, no shadows or distortion, half the bots and particles, 30 FPS cap; lowers the resolution by itself if FPS < 25. On by default on phones (Settings → Graphics → \"Lite mode\"; or ?lite=1 / ?lite=0 in the link).":"Lahki način za šibke telefone: nižja ločljivost, brez senc in popačenj, polovica botov in delcev, omejitev na 30 FPS; sam zniža ločljivost, če je FPS < 25. Na telefonih je privzeto vklopljen (Nastavitve → Grafika → »Lahki način«; ali ?lite=1 / ?lite=0 v povezavi).",
"Phone: new controls. Left — move, right — look (both sticks appear under your finger). Left thumb alone — \"auto\"; when the right one is used, the trooper fires by itself only while the crosshair is on an enemy. Tap an enemy — rocket or grenade, 2 taps — reflex, 3 taps — artillery strike. Auto reload. Jetpack — a button at the left edge. Bottom corners are free, minimap in the corner, hints can be closed with a cross, the objective can be collapsed. Old layout: Settings → Phone.":"Telefon: nove kontrole. Levo — hoja, desno — pogled (obe palici se pojavita pod prstom). Samo levi palec — »samodejno«; ko uporabljaš desnega, vojak strelja sam le, dokler je merek na sovražniku. Dotik na sovražnika — raketa ali granata, 2 dotika — refleks, 3 dotiki — topniški udar. Samodejno ponovno polnjenje. Jetpack — gumb ob levem robu. Spodnja kota sta prosta, minikarta v kotu, namige lahko zapreš s križcem, nalogo lahko skrčiš. Stara postavitev: Nastavitve → Telefon.",
"Hints (pop-ups and curator) — one switch in settings. Who you play as (unit or vehicle type) — \"You: …\" label in the HUD. Rifle and MG optics are transparent. The \"Arsenal\" panel is docked to the right, collapsible and switchable. \"Solo without squad\" (J) is removed. The strategist voice no longer repeats the same line. Tanks get a turret-vs-hull indicator. The cursor no longer disappears at the start of the strategy tutorial.":"Namigi (pojavna okna in Vodnik) — eno stikalo v nastavitvah. Kdo si (vrsta vojaka ali vozila) — napis »Ti: …« v HUD-u. Optika puške in mitraljeza je prozorna. Plošča »Arzenal« je pripeta na desno, jo je mogoče zviti in izklopiti. »Solo brez oddelka« (J) je odstranjen. Glas stratega ne ponavlja več iste vrstice. Tanki dobijo kazalnik kupole glede na trup. Kazalec ne izgine več na začetku urjenja strategije.",
