"Voice of hints & curator":"Glas namigov in Kuratorja",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"Telefon: trije načini igralnih palic. Samo leva — »samodejno« (močan magnet, šibkejši streli). Samo desna — merek se vklopi sam, močnejši magnet, boljša natančnost. Obe — brez merjenja, šibkejši magnet in natančnost. Gumb 👁 na desni skrije/vrne HUD.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"Telefon: strategija poenostavljena — samo inženir in zgradbe. Kartice na levi (inženir, štab, vojašnica…): dotik — kamera poleti tja, spodnja vrstica pokaže, kaj graditi/izdelovati. »V boj« — zgoraj levo. Vojska se bori sama. Polna strategija — Nastavitve → Telefon.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"Prevzem nadzora — dve stikali: »Oddelki« in »Vozila« (vozila so na telefonih privzeto izklopljena — vozi jih AI). Ko so vozila izklopljena, E (telefon: gumb na desni) ob prijateljskem vozilu — sedi za njegov top: vozi samo, ti streljaš. Stari lasten vrstni red razredov je pod »Napredno«. Enota odgovori po radiu, ko prevzameš nadzor.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"Pametni namigi: osnovni namigi se sami ugasnejo po 2. zagonu, a igra te opozori na funkcijo, ki je nikoli ne uporabljaš. Stikala: osnovni / napredni / redki, posebej za glas namigov in Kuratorja.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"Refleks se polni z ubojstvi (nizi polnijo bolj). Soborci so zaostali ali padli — AI-strateg ti spusti nove (dražje kot običajna okrepitev). Grafika in zvok v7.2gfx sta vključena: razpihani eksplozijski oblaki, dim, razbitine, akustika jaškov in kraterjev. Datum izdaje je zdaj pravi.",
