"The sky is a portal: fly up and you come out on the opposite side of the meteor.":"Nebo je portal: ko poletiš navzgor, prideš ven na nasprotni strani meteorja.",
"Follow the strategist's orders — XP for them is doubled and tripled.":"Izvajaj ukaze stratega — izkušnje zanje se podvojijo in potrojijo.",
"X — instantly switch to the squad or vehicle closest to the fight.":"X — takoj preklopi na oddelek ali vozilo, ki je najbližje boju.",
