"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"Kariera in shranjene igre ostanejo nedotaknjene. V boju je isti meni gumb »🛠 Meni« zgoraj desno{0}.",
"New developer match":"Nova razvijalska tekma",
"all unlocked, endless ore, instant build, arsenal":"vse odklenjeno, neskončna ruda, takojšnja gradnja, arzenal",
"Trainings — all 4":"Urjenja — vsa 4",
"PC and phone (strategy and shooter)":"PC in telefon (strategija in strelec)",
"Cinema: split screen":"Kino: razdeljen zaslon",
