"Cinema: everything built":"Kino: vse zgrajeno",
"both bases built and upgraded — for footage":"obe bazi zgrajeni in nadgrajeni — za snemanje",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"Kino način — razdeljen zaslon: levo bot-strateg (pogled od zgoraj na bazo in vojsko), desno bot-strelec iz prve osebe. Gumbi spodaj (tipki S, P): »Razdeljen zaslon« in »★ Vse zgrajeno« — obe bazi zgrajeni in nadgrajeni za snemanje.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"Jedra in rovov skozi meteor ni več — meteor je masiven, boj poteka samo na površju.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"Telefon: 👁 skrije HUD, a pusti jetpack, ⇆, palčki in oznako cilja. »◎ Ciljanje« (samo desni prst) — občutno močnejši in širši magnet; moč magneta za vse tri načine — Nastavitve → Upravljanje → »Napredno«. Pri topu na vozilu se gumb imenuje »Izstopi«.",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"Urjenje: telefon prikaže samo telefonska urjenja, računalnik — samo računalniška. Vsa 4 so v meniju »🛠 Razvijalec«. Razvijalski način in Arzenal sta zdaj en meni (v boju — »🛠 Meni« zgoraj desno, na računalniku F8).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"Grafična sloga »Dendy (8-bitni)« in »16-bitni«: Nastavitve → Grafika → »Grafični slog« (podrobnosti — gumb ⚙). Če je FPS v prvih ~10 s tekme pod 24, se Dendy vklopi sam (pod 20 — večji pikseli, 120 vrstic); obvestilo »nazaj na običajno« trajno povrne običajno grafiko. Tvoja izbira v meniju vedno prevlada.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"3D modeli okolja (ruševine, razbitine, utrdbe) — samo dobro ocenjeni, naloženi po potrebi. Izklop: Nastavitve → Grafika → »Novi 3D modeli okolja«.",
