"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"Vojaki lahko gradijo: E (na telefonu »Vstopi«) ob svojem gradbišču — vojak gradi sam, bližnji soborci pomagajo. Če so inženirji zasedeni, te strateg sam prosi za pomoč — oznaka »GRADBIŠČE«.",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"Oznake stratega: strateg postavi ⌖ na skupino sovražnikov v tvoji bližini — topništvo udari 8 s pozneje, bližnji MLRS »Grad« pa izstrelijo plaz raket. Tudi tvoj topniški udar iz strateškega načina dobi podporo »Grada«.",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"Skrivališča orožja v tovornih kontejnerjih in strmoglavljenih satelitih (📦 vidno s 70 m): E — težka mitraljeza za 90 s, vžigalni naboji ali rakete, poleg tega polne granate. Plazenje: Ctrl — lezi / vstani (nižje, mirneje in natančneje, a počasi).",
