"Link copied":"Povezava kopirana",
"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"»▶ Igraj zdaj« — prvi gumb v meniju: kratek prelet pod nebesnim portalom in takoj v boj (preskok — poljubna tipka ali dotik).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"Zadetki se čutijo: kovinski zvok in iskre, oznaka uničenja ob nišnici (strel v glavo — rumena), serija ×N, mehko tresenje od eksplozij, počasen posnetek ob ključnih uničenjih. Tresenje, počasen posnetek in namig lahko izklopiš v Nastavitvah.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Rezultat tekme: čas, uničenja, najboljša serija, ★ MVP in najboljša četa, kartica tekme — »⇪ Deli«, PNG ali povezava do igre.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"Namig »kaj storiti zdaj« levo pod viri: ukaz stratega, točka za zavzetje, napad Roja. ✕ ali F7 — zloži.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"Boj se shrani sam, če zapreš ali skriješ zavihek — »⟲ Nadaljuj« v meniju.",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"Različica v7.5 ostaja v meniju »🕘 Različica igre« — če ti nova ne bo všeč. Anonimna statistika (brez imen in e-pošte) se zdaj pošilja; izklop — v Nastavitvah.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"»Igraj zdaj«, odziv zadetkov, rezultat tekme s kartico, namig »kaj storiti«, samodejno shranjevanje",
"and older: v7.5, v7.4, milestones v1–v7.0":"in starejše: v7.5, v7.4, mejniki v1–v7.0",
"New in v7.6":"Novo v v7.6",
"NEW IN v7.6":"NOVO V v7.6",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Izbira frakcije pred tekmo: »Konzorcij« (težka pehota v pogonskih oklepih, oklepi in topništvo) ali »Roj« (hitrost, krdela dronov, težki streli z izkrivljanjem). Drugo igra UI.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"Vsaka frakcija ima svoja vozila in edinstvene stvari: Konzorcij — tank »Rhino« in »Keramitne plošče«, Roj — »Krdelo dronov« in »Fazni jetpacki«. Ravnovesje je preverjeno s tekmami botov.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Krateri eksplozij: artilerija, rakete in tankovski topovi kopljejo jame v meteor — po njih lahko hodiš in voziš, v njih pa se lahko skriješ.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Pogled iz tretje osebe za vojaka (V, si ga zapomni; na telefonu — Upravljanje) in gladka kamera vozila z oznako, kamor bo zadel top.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"v7.6 ostaja v meniju »🕘 Različica igre«, če ti bo bolj všeč.",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"Frakciji Konzorcij / Roj z izbiro pred tekmo, krateri eksplozij, pogled iz tretje osebe",
