"Drops a crate near your forces: ammo, grenades, rockets, weapon parts, a repair kit.":"Spusti zaboj blizu vaših sil: naboji, granate, rakete, deli orožja, komplet za popravilo.",
"\"Grad\" rocket strike":"Udar »Grada«",
"16 rockets over a wide area after 3 seconds — faster and wider than artillery.":"16 raket čez veliko območje čez 3 sekunde — hitreje in širše od topniškega udara.",
"Support: crate, recon, \"Grad\", artillery (then 1–4)":"Podpora: zaboj, izvidništvo, »Grad«, topniški udar (nato 1–4)",
"WARNING: Swarm \"Grad\" incoming on your area!":"POZOR: »Grad« Roja po vašem območju!",
"Warning! Rocket salvo on our position!":"Pozor! Raketna salva na naš položaj!",
"take the supply crate":"vzemi zaboj z zalogami",
"Anomalies on the meteor (wave 1): the \"Singing Vein\" — a glowing green crystal that hums and strikes everyone nearby with rhythmic pulses; the \"Whirlpool\" pulls and slams, the \"Crackler\" arcs between rods, the \"Brazier\" bursts into flame underfoot, the \"Acid mist\" and the \"Lens\" (bends bullets and your view) drift around.":"Anomalije na meteorju (val 1): »Pojoča žila« — svetleč zelen kristal, ki brenči in z ritmičnimi sunki udarja vse v bližini; »Vrtinec« vleče in meče, »Pokalec« sproža strele med palicami, »Žerjavica« zaplamti pod nogami, »Kisla megla« in »Leča« (krivi krogle in sliko) lebdita naokoli.",
"You can feel anomalies in advance (hum, glow, heat haze). Discharge one with a grenade, a rocket or a bolt (E near it): it goes dormant and sometimes leaves an artifact with a plus and a minus. Your squad warns over the radio, and enemies (and friends) sometimes blunder in — lure them!":"Anomalije začutiš vnaprej (brenčanje, sij, vroč zrak). Sprosti jih z granato, raketo ali vijakom (E ob njej): zaspi in včasih pusti artefakt s plusom in minusom. Oddelek te opozarja po radiu, sovražniki (in prijatelji) pa včasih zlezejo vanje — zvabi jih!",
"Support for command points: 4 in battle (📡 on the phone) — supply drop, recon scan, \"Grad\" rocket strike, artillery at the crosshair. The strategist sees anomalies on the map only after a scan.":"Podpora za poveljniške točke: 4 v boju (📡 na telefonu) — zaboj z zalogami, izvidniški sken, udar »Grada«, topniški udar po ciljniku. Strateg vidi anomalije na zemljevidu šele po skenu.",
"Supply crates in ruins of old expeditions, near the HQs and next to finished buildings: ammo, grenades, rockets, weapon parts (they unlock attachments).":"Zaboji z zalogami v ruševinah starih odprav, ob štabih in ob dokončanih stavbah: naboji, granate, rakete, deli orožja (odklenejo dodatke).",
"v7.7 stays in the \"🕘 Game version\" menu. Anomalies can be turned off in Settings.":"v7.7 ostaja v meniju »🕘 Različica igre«. Anomalije lahko izklopiš v Nastavitvah.",
"Anomalies (the \"Singing Vein\" and 5 more), discharge with a bolt or grenade, artifacts, support calls for CP, supply crates":"Anomalije (»Pojoča žila« in še 5), sprostitev z vijakom ali granato, artefakti, klici podpore za PT, zaboji z zalogami",
"and older: v7.7, v7.6, milestones v1–v7.0":"in starejše: v7.7, v7.6, mejniki v1–v7.0",
