"Close":"Zapri",
"Anomalies on the meteor":"Anomalije na meteorju",
"☰ in the corner opens the pause menu: Resume, Restart, Training, Graphics, Settings, Main menu (with confirmation). Phone: ☰ at the top right (battle actions — the \"⚡ Actions\" tile); PC: the \"☰ Menu\" button at the top right or Esc.":"☰ v kotu odpre meni premora: Nadaljuj, Začni znova, Urjenje, Grafika, Nastavitve, Glavni meni (s potrditvijo). Telefon: ☰ zgoraj desno (bojna dejanja — ploščica »⚡ Dejanja«); računalnik: gumb »☰ Meni« zgoraj desno ali Esc.",
"Graphics are always normal by default — Dendy only if you pick it: the \"Graphics: Normal / Dendy (8-bit) / 16-bit\" switch is right in the main menu and the pause menu. If the game lags badly, a tip with a \"Turn on Dendy\" button appears.":"Grafika je privzeto vedno običajna — Dendy le po tvoji izbiri: stikalo »Grafika: Običajna / Dendy (8-bitna) / 16-bitna« je kar v glavnem meniju in meniju premora. Če igra močno zaostaja, se pojavi namig z gumbom »Vklopi Dendy«.",
"Phone and tablet: the \"✋\" action button on the right appears only when there is something to do nearby — \"Take\" (cache, crate), \"Board\" (vehicle, turret, gun), \"Build\", \"Get off\", \"Bolt\" at an anomaly. You can also just tap the highlighted object.":"Telefon in tablični računalnik: gumb dejanja »✋« desno se pojavi le, kadar je v bližini kaj za narediti — »Vzemi« (skrivališče, zaboj), »Vstopi« (vozilo, kupola, top), »Gradi«, »Stopi dol«, »Vijak« ob anomaliji. Lahko pa tudi samo tapneš označen predmet.",
"Phone, strategy: hold a finger ~0.3 s (the phone buzzes, a yellow ring appears) and drag — a selection box; a normal swipe moves the camera. There is also the \"Box\" button on the right; in the training the \"Box\" step also accepts tapping a squad.":"Telefon, strategija: drži prst ~0,3 s (telefon zavibrira, pojavi se rumen obroč) in vleci — okvir za izbiro; navaden poteg premika kamero. Na desni je tudi gumb »Okvir«; v urjenju korak »Okvir« upošteva tudi izbiro oddelka z dotikom.",
"Phone: tiny buttons are easier to hit, the 📡 support list is bigger, strategy panels no longer cover the pause and results screens. v7.8 stays in the \"🕘 Game version\" menu.":"Telefon: majhne gumbe je lažje zadeti, seznam podpore 📡 je večji, strateške plošče ne prekrivajo več premora in rezultatov. v7.8 ostaja v meniju »🕘 Različica igre«.",
"☰ menu on phone and PC, no auto-Dendy, \"✋\" button on touch, box selection on phone":"Meni ☰ na telefonu in računalniku, brez samodejnega Dendyja, gumb »✋« na dotik, izbira z okvirjem na telefonu",
"16-bit":"16-bitna",
"Lagging? Try the Dendy graphics — they are lighter.":"Zaostaja? Poskusi grafiko Dendy — je lažja.",
