"Pause: resume, restart, training, graphics, settings, main menu":"Premor: nadaljuj, znova, urjenje, grafika, nastavitve, glavni meni",
"Menu: pause, restart, training, graphics, settings":"Meni: premor, znova, urjenje, grafika, nastavitve",
"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"Drži prst na tleh ~0,3 s — telefon zavibrira in pojavi se rumen obroč — nato brez dviga vleci: nastane okvir. Ali pa gumb »Okvir« na desni. Dovolj je tudi samo tapniti oddelek.",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"Za celozaslonski način na iPhonu: »Deli« ⬆ → »Dodaj na začetni zaslon« — igra se odpre brez Safarijevih vrstic.",
"Open portal-meteor.pages.dev for that.":"Za to odpri spletno mesto portal-meteor.pages.dev.",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"Dotik — izberi · dotik tal — pojdi · drži — meni ukazov · drži in vleci — okvir · 2 prsta — povečava",
"Robo-ninja":"robo-ninja",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"Junakinja-morilka: sunki-teleporti, katana, shurikeni. Sama skače po sovražnikovih conah in reže robote. 1 na stran.",
"Shadow protocol":"Protokol »Senca«",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"Raziskava: odklene robo-ninjo v Vojašnici. Potrebna je dokončana tovarna mehov.",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"Junakinja (1 na stran): sama se teleportira po sovražnikovih conah in reže robote; lahko prevzameš nadzor in igraš ročno.",
"is ready. She works on her own (AUTO) — possess her to play manually":"je pripravljena. Dela sama (AVTO) — prevzemi nadzor, da igraš ročno",
