"⚔ NINJA DUEL! Block right before a hit to parry, blink to dodge. Watch for the wind-up flash":"⚔ DVOBOJ NINDŽ! Blok tik pred udarcem je odbitje, sunek je izmik. Pazi na bliskanje zamaha",
"The two ninjas have met in a duel!":"Dve nindži sta se srečali v dvoboju!",
