"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ AVTO: sama skače po sovražnikovih conah in reže. Joystick / WASD — premor 1.5 s",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ Ročno: dotik sovražnika — sunek in udarec, poteg — zamah, 🛡 — blok",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ Ročno upravljanje: levi klik — katana, desni klik — blok, Shift — sunek, Q — shurikeni, G — teleport",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ Nindža: dotik na sovražnika — sunek in udarec, poteg desno — zamah, ● — udarec, 🛡 — blok (ob pravem času = parada), ⇑ — blink, ✦ — shurikeni, ◎ — teleport, AVTO — sama",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ Nindža: levi klik — katana (drži — težki udarec), desni klik — blok (ob pravem času = parada), Shift/Z — blink, Q — shurikeni, G — teleport do križca, skok v zraku — dvojni skok / tek po steni, {0} — AVTO",
