"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"Radio Portal Meteor: 100+ skladb EDMITRY kar v igri — gumb 📻 (PC: tipka 5, [ ] — skladba). Glasba se pretaka po potrebi in igre ne obremenjuje; glasnost in samodejni zagon v nastavitvah, povezava »Poslušaj na Spotifyju«.",
