"📻 on the right — Radio Portal Meteor: music by EDMITRY while you fight.":"📻 desno — Radio Portal Meteor: glasba EDMITRY med bojem.",
"{0} — Radio Portal Meteor: music by EDMITRY while you fight. [ ] — track.":"{0} — Radio Portal Meteor: glasba EDMITRY med bojem. [ ] — skladba.",
"Radio Portal Meteor (EDMITRY): volume":"Radio Portal Meteor (EDMITRY): glasnost",
"Radio: start by itself in battle":"Radio: samodejni zagon v boju",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"Robo-nindža: kiborg s katano. Odklene se v Vojašnici z raziskavo »Protokol Senca« (potrebna je tovarna robotov). Sama se teleportira v sovražnikove cone, razseka sovražnike (brez krvi — iskre), izvaja sunke, meče shurikene, se dvobojuje s sovražno nindžo. Prevzemi jo — način AVTO ali ročno upravljanje (na telefonu — lastni gumbi).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Tipka 5 (spremenljiva), na telefonu — ☰ → Nastavitve → Zvok. Glasnost in »samodejni zagon v boju« sta v nastavitvah; glasba se ob eksplozijah in radijskem glasu utiša.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"Novi jeziki: uzbeščina in tadžiščina — v celoti; kitajščina, španščina, portugalščina — delno. Nova izbira jezika v meniju ob »Nova tekma«.",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"Telefon: »skrij ikone« 👁 zbere preostale gumbe v urejen stolpec ob desnem robu; pokončni način se ne prekriva več; iPhone — igra se ne bori več s kretnjami Safarija, »Deli → Dodaj na začetni zaslon« pa jo zažene čez cel zaslon.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"Iz v7.8.1: kotni meni ☰ (pavza, znova, urjenje, grafika), brez samodejnega Dendyja, gumb dejanja ✋ na telefonu. v7.8.1 in v7.8 ostaneta v meniju »🕘 Različica igre«.",
"Robo-ninja, EDMITRY radio, Uzbek and Tajik, phone and iPhone UX":"Robo-nindža, radio EDMITRY, uzbeščina in tadžiščina, udobje na telefonu in iPhonu",
