"Selected squads go into the nearest open tunnel and come out at the other end":"Izbrani oddelki gredo v najbližji odprt predor in pridejo ven na drugem koncu",
"Into tunnel":"V predor",
"\"Bastion\"":"»Bastion«",
"Super-heavy tank":"Supertežki tank",
"\"Reaper\"":"»Reaper«",
"Walker":"Hodec",
"Assembly hall":"Montažna hala",
"Consortium. From 12:00. Builds the super-heavy tank \"Bastion\" (one per army).":"Konzorcij. Od 12:00. Tu sestavljajo supertežki tank »Bastion« (eden na vojsko).",
"Incubator":"Inkubator",
"Swarm. From 12:00. Grows the \"Reaper\" walker (one per army).":"Roj. Od 12:00. Tu raste hodec »Reaper« (eden na vojsko).",
"Super-heavy tank \"Bastion\"":"Supertežki tank »Bastion«",
"Consortium. Boss: 15000 hull, cannon, 2 MGs, rockets. Very slow. Weak spot — the rear. One per army.":"Konzorcij. Šef: 15000 oklepa, top, 2 mitraljeza, rakete. Zelo počasen. Šibka točka — zadek. Eden na vojsko.",
"Walker \"Reaper\"":"Hodec »Reaper«",
"Swarm. Boss: 12500 hull, distortion beam, stomp. Steps over barriers. Weak spot — the core underneath. One per army.":"Roj. Boss: 12500 oklepa, žarek popačenja, teptanje. Prestopi pregrade. Šibka točka — jedro pod trebuhom. Eden na vojsko.",
"Limit: 1 per army":"Omejitev: 1 na vojsko",
