"⚠ WARNING: the enemy is assembling the {0}!":"⚠ POZOR: sovražnik sestavlja {0}!",
"Warning! The enemy is assembling the {0}. Find and destroy the plant before it is too late.":"Pozor! Sovražnik sestavlja {0}. Poiščite in uničite obrat, preden je prepozno.",
"⚠ WARNING: the enemy {0} is on the battlefield!":"⚠ POZOR: sovražnikov {0} je na bojišču!",
"Warning! The enemy {0} is on the field!":"Pozor! Sovražnikov {0} je na bojišču!",
"Weak spot! Nearly double damage":"Šibka točka! Skoraj dvojna škoda",
