"Strip: ⟳ to rotate, or drag from the target along the run":"Pas: ⟳ za vrtenje ali povleci od cilja v smeri naleta",
"Strip: mouse wheel or R to rotate, or drag from the target along the run":"Pas: kolešček miške ali R za vrtenje ali povleci z miško od cilja v smeri naleta",
"Into the tunnel: {0} vehicle(s)":"V predor: vozil {0}",
"Light and medium vehicles go into the nearest open tunnel":"Lahka in srednja vozila gredo v najbližji odprt predor",
"Swarm. Squads within 70 m of the burrow (and selected ones), plus selected light/medium vehicles (Jackal, Hammer, Grad), go through the tunnel. Or: select and RMB/tap the burrow.":"Roj. Oddelki v 70 m od rova (in izbrani) ter izbrana lahka/srednja vozila (Šakal, Kladivo, Grad) gredo skozi predor in izidejo na drugem koncu. Ali: izberi in desni klik/dotik na rov.",
"Air strikes":"Zračni udari",
"Carpet bombing and napalm: aiming, rotating the strip, enemy warning, calling from battle":"Preprogasto bombardiranje in napalm: ciljanje, vrtenje pasu, opozorilo sovražnika, priklic iz boja",
"Terrain and lakes":"Teren in jezera",
"Lava burns, ice slides, methane explodes from fire, the rock hangar is cover":"Lava žge, led drsi, metan eksplodira od ognja, skalni hangar je kritje",
"Swarm: tunnels":"Roj: predori",
"You play the Swarm: tunnel burrow, exit up to 220 m, dust warning, squads and vehicles through":"Igraš za Roj: Rov-predor, izhod do 220 m, opozorilo s prahom, oddelki in vozila skozi predor",
"Consortium: fortifications":"Konzorcij: utrdbe",
"You play the Consortium: barrier chains, repair post, field repair by builders":"Igraš za Konzorcij: veriga betonskih pregrad, popravljalna postaja, terensko popravilo z inženirji",
"Bosses":"Bossi",
"\"Bastion\" and \"Reaper\": from 12:00 (skipped here), plant, assembly, orders, weak spots, possession":"»Bastion« in »Reaper«: od 12:00 (tu preskočeno), tovarna, sestava, ukaz, šibke točke, prevzem nadzora",
