"MY SQUADS":"MOJI ODDELKI",
"Veterancy carries over between battles. A squad earns XP (infantry 1, building 2, vehicle 3), levels, stars and perks. Veterans deploy first in a new battle. A lost squad loses everything and joins the Fallen.":"Veteranstvo se ohranja med bitkami. Oddelek zbira izkušnje (pehota 1, zgradba 2, vozilo 3), pridobiva stopnje, zvezde in perke. V novi bitki se veterani razporedijo prvi. Padel oddelek izgubi vse in odide med Padle.",
