"Suppressing fire":"Zaporni ogenj",
"Saturating fire on a 14 m area: enemies slowed and missing (7 s).":"Zaporni ogenj po območju 14 m: sovražniki so upočasnjeni in zgrešajo (7 s).",
"Field medic":"Poljski bolničar",
"+20% hull to all at once, then 4 s of repair.":"Takoj +20 % trdnosti vsem, nato popravilo še 4 s.",
"Regen burst":"Izbruh regeneracije",
"Swarm: 8 s of fast regeneration for the whole squad.":"Roj: 8 s hitre regeneracije za ves oddelek.",
"Grenade volley":"Plaz granat",
"Every trooper throws a grenade at the point.":"Vsak vojak vrže granato v točko.",
"AT rocket":"Protitankovska raketa",
"Heavy rockets at a vehicle or building (up to 3).":"Težke rakete po vozilu ali zgradbi (do 3).",
"Mini barrier":"Mini pregrada",
"Consortium: a concrete section in front of the squad for 40 s.":"Konzorcij: betonski element pred oddelkom za 40 s.",
"No squads to command — order a squad":"Ni oddelkov za poveljevanje — naroči oddelek",
"Commander: {0}. LMB — move / attack, 1–4 — abilities, Tab — next squad, double-click a trooper — fight, P — strategy":"Poveljnik: {0}. levi klik — hoja / napad, 1–4 — sposobnosti, Tab — drug oddelek, 2× na vojaka — v boj, P — strategija",
"Tap — move/attack, double-tap a trooper — fight, right buttons — abilities":"Dotik — hoja/napad, 2× dotik na vojaka — v boj, gumbi desno — sposobnosti",
