"Point {0} taken, but there is no HQ — no pod will come":"Točka {0} zavzeta, a štaba ni — kapsula ne bo priletela",
"The bomber took off from the base — into the sky, it will come out over the target":"Bombnik je vzletel z baze — odhaja v nebo, izšel bo nad ciljem",
"Select a unit → \"▶ Possess\" or double-tap. Mode button at the top right: Strategist → Commander → Shooter.":"Izberi enoto → »▶ Prevzemi nadzor« ali dvojni dotik. Gumb načina zgoraj desno: Strateg → Poveljnik → Strelec.",
"Select a unit → \"▶ Possess\" or double-click. {0} cycles: Strategist → Commander → Shooter.":"Izberi enoto → »▶ Prevzemi nadzor« ali dvojni klik. {0} — v krogu: Strateg → Poveljnik → Strelec.",
