"SABOTAGE":"SABOTAŽA",
"Living world: requests, hero quests, breakthrough ops":"Živ svet: prošnje svojih, naloge herojev, preobrat boja",
"Living world":"Živ svet",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Svoji prosijo za pomoč in te nagradijo, heroji dajejo naloge, zavlečeno fronto zlomiš z operacijo",
"A request":"Prošnja svojih",
"Breakthrough":"Preobrat boja",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Svoji občasno prosijo za pomoč: glas po radiu, kartica »PROŠNJA« in oznaka ✋. Oddelek je pritisnjen — uniči sovražnike ob njem. Nagrada: vojak s kapsulo iz baze, orožje iz prtljažnika bugyja, mesto strelca ali krinka iz orbite. Če nočeš — ✕ ali preprosto ignoriraj.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"Veteran izvidnik »Sova« ponuja nalogo. Y — sprejmi (N — zavrni). Pojdi do oznake ★, odstrani stražo in ostani ob pilotu 3 s — pridruži se ti v oddelku.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"Fronta je obstala — štab ponuja preobrat. Y — sprejmi. Drži rele 8 s brez sovražnikov v bližini: sovražnikova karta je vidna 60 s. Generator — sovražnikove turete molčijo 2 min. V načinu Strateg — »Dodeli oddelku«. Tudi sovražnik to zna: pazi na ⚠.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Svoji prosijo za pomoč: kartica »PROŠNJA« in oznaka ✋. Uniči sovražnike ob pritisnjenem oddelku — dobiš nagrado. ✕ — preskoči.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"Heroj »Sova« ponuja nalogo — dotakni se »Sprejmi«. Pojdi do ★, odstrani stražo, ostani ob pilotu.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"Fronta je obstala — dotakni se »Sprejmi« in drži rele 8 s: sovražnikova karta se odpre za minuto.",
"Pod redeploy from the base: {0} m — through the sky portal":"Prevoz s kapsulo iz baze: {0} m — skozi nebesni portal",
"Pod away from the base! Hold on — exit over the target.":"Kapsula je odletela iz baze! Držite se — izstop nad ciljem.",
"Landed at the objective!":"Pristanek pri cilju!",
"LAUNCH FROM BASE":"IZSTREL IZ BAZE",
"LANDING":"PRISTANEK",
"REDEPLOY":"PREVOZ",
"Steel fluff stuck to you — corrodes armour −2/s. Stand still 3 s out of combat or find an engineer":"Jeklena puh se je prilepila — razjeda oklep −2/s. Stoj 3 s izven boja ali poišči inženirja",
"An engineer brushed the fluff off":"Inženir je očistil puh",
"The fluff fell off — armour is safe":"Puh je odpadel — oklep je cel",
"The firefly swarm scattered by the blast":"Roj kresnic je razgnan z eksplozijo",
"STEEL FLUFF −2/s · stand still 3 s or find an engineer":"JEKLENA PUH −2/s · stoj 3 s izven boja ali k inženirju",
"Lefty's convoy is ready: two Jackals. Stay close — they wait for you":"Konvoj Levaka je pripravljen: dva »Šakala«. Drži se blizu — čakata nate",
"The convoy is waiting for you":"Konvoj te čaka",
"Ambush! Cover the Jackals!":"Zaseda! Pokrij »Šakale«!",
"the convoy made it ({0} of 2)! +2 CP, +150 ore, the Jackals are yours":"konvoj je prispel ({0} od 2)! +2 PT, +150 rude, »Šakali« so tvoji",
"The parts are delivered! Thanks, commander.":"Deli so na mestu! Hvala, poveljnik.",
"Show tips again":"Znova prikaži namige",
"Reset":"Ponastavi",
"Sure? Tap again":"Prepričan? Tapni še enkrat",
"Done":"Končano",
"Tips and lessons will show again":"Namigi in lekcije se bodo spet prikazali",
