"Fluff in the air — keep out of the meadow and away from the infected!":"Puhljica leti — ne hodi na jaso in se ne drgni ob okužene!",
"fluff blown away, dormant for 25 s · +0.5 CP":"puhljica odpihnjena, jasa miruje 25 s · +0,5 TU",
"My crew is hauling parts to point {0}. Escort the column — there may be an ambush.":"Moja ekipa vozi dele na točko {0}. Spremljaj kolono — na poti utegne čakati zaseda.",
