"Main battle tank: cannon and MG. Consortium \"Bulldog\" is tougher, Swarm \"Spider\" is faster.":"Glavni bojni tank: top in strojnica. Konzorcijev »Buldog« je trpežnejši, rojev »Pajek« hitrejši.",
