"Autonomous flying gunner: fast, fragile, fears anti-air.":"Samodejni leteči strelec: hiter, krhek, boji se protiletalske obrambe.",
"Upgrade":"Izboljšava",
"Longer, faster jetpacks for all infantry.":"Daljši in hitrejši jetpacki za vso pehoto.",
"Extractors mine more ore.":"Ekstraktorji pridobivajo več rude.",
"Army-wide levels: less damage taken / more damage dealt.":"Stopnje za celotno vojsko: manj prejete škode / več povzročene škode.",
"Levels":"Stopenj",
"Base":"Baza",
"Heart of the base: squads, engineers, pods, research. Lose it and you lose.":"Srce baze: oddelki, inženirji, kapsule, raziskave. Izguba štaba pomeni poraz.",
"Produces: ":"Proizvaja: ",
"Launch pad":"Izstrelišče",
"A silo next to the HQ: pods, supply crates and bombers launch from here through the sky portal. Nothing can be built on it.":"Silos ob štabu: od tod skozi nebesni portal do cilja štartajo kapsule, zaboji z oskrbo in bombniki. Nanj ni mogoče graditi.",
"Economy":"Ekonomija",
"Key building":"Ključno",
"Weak spot — the rear (engine): damage ×{0}. Cannon, 2 MG turrets, rocket pod; turns very slowly — flank it.":"Šibka točka — zadek (motor): škoda ×{0}. Top, 2 strojnični kupoli, raketni zaboj; zelo počasi se obrača — obidi ga s boka.",
"Weak spot — the glowing core underneath: damage from below ×{0}. Distortion beam and area stomp; steps over barriers — keep distance, don't bunch up.":"Šibka točka — žareče jedro pod trebuhom: škoda od spodaj ×{0}. Žarek popačenja in stampanje po območju; prestopi pregrade — drži razdaljo, ne stoj v gruči.",
"Counter: bombs and artillery (×{0}), rockets (×{1}), carpet bombing; bullets barely scratch it (×{2}).":"Proti: letalske bombe in topništvo (×{0}), rakete (×{1}), preprogasto bombardiranje; naboji komaj opraskajo (×{2}).",
"Faction":"Frakcija",
"Fast machines, drone packs, tunnels and regeneration. Lighter but faster infantry; cannons and rails hit harder.":"Hitri stroji, roji dronov, predori in regeneracija. Pehota je lažja, a hitrejša; topovi in tirni topovi udarijo močneje.",
"Heavy power-armoured infantry, concrete barriers, repair and artillery. Slower but tougher.":"Težka pehota v pogonskih oklepih, betonske pregrade, popravila in topništvo. Počasnejša, a trpežnejša.",
